def ref_same(a,b):
    if not is_object(a) or not is_object(b):
        return False
    for key in ['identity','revision','scope','owner']:
        if not has(a,key) or not has(b,key) or get(a,key) is None or get(b,key) is None or not json_equal(get(a,key),get(b,key)):
            return False
    if has(a,'sha256') and has(b,'sha256') and get(a,'sha256') is not None and get(b,'sha256') is not None:
        return json_equal(get(a,'sha256'),get(b,'sha256'))
    return True

def ref_collections_same(a,b):
    if not is_array(a) or not is_array(b):
        return False
    for left in a:
        found = False
        for right in b:
            if ref_same(left,right):
                found = True
        if not found:
            return False
    for right in b:
        found = False
        for left in a:
            if ref_same(left,right):
                found = True
        if not found:
            return False
    return True

def binding_same(a,b):
    if not is_object(a) or not is_object(b):
        return False
    for key in ['template_ref','knowledge_ref','requirement_ref','oracle_ref','pack_ref']:
        if not ref_same(get(a,key),get(b,key)):
            return False
    for key in ['pack_contract_version','pack_artifact_version','version_target']:
        if not has(a,key) or not has(b,key) or not json_equal(get(a,key),get(b,key)):
            return False
    return ref_collections_same(get(a,'pack_dependency_versions'),get(b,'pack_dependency_versions'))

def snapshot_input(v):
    if is_object(v) and is_object(get(v,'input')):
        return get(v,'input')
    return {}

def source_usable(v,ref):
    inp = snapshot_input(v)
    if not is_array(get(v,'unusable_source_refs')):
        return False
    for bad in as_list(get(v,'unusable_source_refs')):
        if ref_same(bad,ref):
            return False
    for source in as_list(get(inp,'sources')):
        if ref_same(get(source,'ref'),ref) and get(source,'role') == 'semantic_json':
            return True
    return False

def owner_body_equal(a,b,excluded_key):
    return is_object(a) and is_object(b) and json_equal(without_key(a,excluded_key),without_key(b,excluded_key))

def fact_usable(v,fact):
    if not is_object(fact) or not source_usable(v,get(fact,'source_ref')):
        return False
    for source in as_list(get(snapshot_input(v),'sources')):
        if ref_same(get(source,'ref'),get(fact,'source_ref')):
            for group in as_list(get(get(source,'content'),'descriptor_facts')):
                for original in as_list(get(group,'facts')):
                    if ref_same(get(original,'ref'),get(fact,'ref')) and owner_body_equal(original,fact,'source_ref'):
                        return True
    return False

def owner_descriptor_attribution(v,slot,fact):
    refs = []
    if is_object(get(fact,'source_ref')):
        refs.append(get(fact,'source_ref'))
    if is_object(get(fact,'ref')):
        refs.append(get(fact,'ref'))
    original_refs = sorted_values(refs)
    binding = get(slot,'binding')
    subject = get(fact,'ref')
    caller_kind = get(slot,'descriptor_kind')
    backflow_owner = None
    knowledge_ref = get(binding,'knowledge_ref')
    if is_object(knowledge_ref):
        backflow_owner = get(knowledge_ref,'owner',None)
    state = 'unknown'
    reason = 'caller factのsource Refに一致するqualified semantic_json sourceがない。'
    matching_kinds = []
    unresolved_kind = False
    invalid_owner_kind = False
    fact_binding_mismatch_seen = False
    source_binding_seen = False
    explicit_reuse_seen = False
    same_ref_body_other_slot = False
    if not is_object(slot) or not is_object(fact) or not is_string(get(slot,'slot_identity')) or not is_string(caller_kind):
        reason = 'caller slot/fact identityまたはkindが未解決。'
    elif not source_usable(v,get(fact,'source_ref')):
        reason = 'caller factは残るが、そのsource Refに一致するqualified semantic_json sourceがない。'
    elif not fact_usable(v,fact):
        reason = 'caller factのRef/bodyをowner source内の原factへ結べない。'
    else:
        approved_kinds = APPROVED_DESCRIPTOR_KINDS
        if caller_kind not in approved_kinds:
            reason = 'caller descriptor_kindがL4 descriptor_meaningsの固定15名へ結べない。'
        else:
            for source in as_list(get(snapshot_input(v),'sources')):
                if not ref_same(get(source,'ref'),get(fact,'source_ref')) or get(source,'role') != 'semantic_json':
                    continue
                content = get(source,'content')
                if not binding_same(get(content,'binding'),binding):
                    continue
                source_binding_seen = True
                for group in as_list(get(content,'descriptor_facts')):
                    for original in as_list(get(group,'facts')):
                        same_fact_body = ref_same(get(original,'ref'),get(fact,'ref')) and owner_body_equal(original,fact,'source_ref')
                        if same_fact_body and not binding_same(get(original,'binding'),binding):
                            fact_binding_mismatch_seen = True
                        same_original = same_fact_body and binding_same(get(original,'binding'),binding)
                        if not same_original:
                            continue
                        if get(group,'slot_identity') != get(slot,'slot_identity'):
                            same_ref_body_other_slot = True
                            other_kind = get(group,'descriptor_kind')
                            if is_string(other_kind) and other_kind in approved_kinds:
                                explicit_reuse_seen = True
                            continue
                        owner_kind = get(group,'descriptor_kind')
                        if not has(group,'descriptor_kind'):
                            unresolved_kind = True
                        elif not is_string(owner_kind) or owner_kind not in approved_kinds:
                            unresolved_kind = True
                            invalid_owner_kind = True
                        else:
                            matching_kinds.append(owner_kind)
            kind_conflict = False
            for kind in matching_kinds:
                if kind != caller_kind:
                    kind_conflict = True
            kind_values = unique_sorted(matching_kinds)
            if len(kind_values) != 0 and len(kind_values) != 1:
                state = 'conflict'
                reason = '同一owner identity/binding/factに異なる既知kindが明示される。'
            elif len(matching_kinds) != 0 and kind_conflict:
                state = 'conflict'
                reason = '固定されたowner kindとcaller kindが同じidentity/binding/factで既知に相違する。'
            elif unresolved_kind:
                reason = 'owner groupのdescriptor_kindが固定15名外または型外で、分類対応を確定できない。' if invalid_owner_kind else '原source/factはあるがowner groupのdescriptor_kindが欠落し、分類対応を確定できない。'
            elif len(matching_kinds) != 0:
                state = 'known'
                reason = 'ownerが異なるslot identity/kindへ同じfact Ref/bodyを個別に明示し、各対応が成立する。' if explicit_reuse_seen else '同じowner source内のidentity・kind・fact Ref/bodyが各caller slotへ一致する。'
            elif same_ref_body_other_slot:
                reason = '原factはqualified owner sourceにあるが、caller slot_identityへの対応groupがない。'
            elif not source_binding_seen:
                reason = 'caller full Bindingとowner source/fact Bindingが一致せず、identityだけでは結合しない。'
            elif fact_binding_mismatch_seen:
                reason = 'caller factとowner原factのfull Bindingがslot Bindingに一致せず、帰属を確定できない。'
    return {'subject_ref':subject,'binding':binding,'axis':'descriptor.attribution','state':state,'original_refs':original_refs,'reason':reason,'backflow_owner':None if state == 'known' else backflow_owner}

def descriptor_attribution_axes(v,slot):
    results = []
    if not is_object(slot) or not is_object(get(slot,'binding')):
        return []
    for fact in as_list(get(slot,'facts')):
        if not is_object(fact) or not is_object(get(fact,'ref')):
            continue
        results.append(owner_descriptor_attribution(v,slot,fact))
    return sorted_values(results)

def selected_bindings(v):
    inp = snapshot_input(v)
    choices = []
    if is_object(get(inp,'binding')):
        choices.append(get(inp,'binding'))
    for slot in as_list(get(inp,'descriptors')):
        if is_object(get(slot,'binding')):
            choices.append(get(slot,'binding'))
    selected = []
    for binding in choices:
        for candidate in as_list(get(inp,'candidates')):
            if is_object(get(binding,'knowledge_ref')) and ref_same(get(binding,'template_ref'),candidate):
                selected.append(binding)
    return unique_sorted(selected)

def required_input_refs(v):
    refs = []
    inp = snapshot_input(v)
    for binding in selected_bindings(v):
        for slot in as_list(get(inp,'descriptors')):
            if get(slot,'descriptor_kind') == 'required input' and binding_same(get(slot,'binding'),binding):
                for fact in as_list(get(slot,'facts')):
                    if binding_same(get(fact,'binding'),binding) and has(fact,'meaning') and get(fact,'meaning') is not None and is_object(get(fact,'ref')) and fact_usable(v,fact) and get(owner_descriptor_attribution(v,slot,fact),'state') == 'known':
                        refs.append(get(fact,'ref'))
    return sorted_values(refs)

def knowledge_material(v,field):
    entries = []
    if field not in ['counterexamples','limits']:
        return None
    for binding in selected_bindings(v):
        matches = []
        for record in as_list(get(snapshot_input(v),'knowledge_records')):
            if ref_same(get(record,'ref'),get(binding,'knowledge_ref')):
                matches.append(record)
        if len(matches) == 0:
            entries.append({'candidate_ref':get(binding,'template_ref'),'knowledge_ref':get(binding,'knowledge_ref'),'presence':'absent'})
        for record in matches:
            entry = {'candidate_ref':get(binding,'template_ref'),'knowledge_ref':get(record,'ref'),'presence':'absent'}
            if has(record,field):
                entry['presence'] = 'explicit_null' if get(record,field) is None else 'supplied'
                entry['value'] = get(record,field)
            entries.append(entry)
    return sorted_values(entries)

def record_original_refs(record):
    refs = []
    if is_object(get(record,'ref')):
        refs.append(get(record,'ref'))
    for ref in as_list(get(record,'provenance_refs')):
        if is_object(ref):
            refs.append(ref)
    for key in ['limited_adoption_ref','evaluation_ref','os_registration_ref','independent_verification_ref','adoption_ref']:
        if is_object(get(record,key)):
            refs.append(get(record,key))
    return sorted_values(refs)

def knowledge_trace_axes(v):
    axes = []
    for binding in selected_bindings(v):
        subject = get(binding,'knowledge_ref')
        if is_object(subject):
            matches = []
            for record in as_list(get(snapshot_input(v),'knowledge_records')):
                if ref_same(get(record,'ref'),subject):
                    matches.append(record)
            state = 'unknown'
            reason = '同一knowledge Refの原KnowledgeRecordが未供給または一意でない。'
            refs = []
            for record in matches:
                for ref in record_original_refs(record):
                    refs.append(ref)
            refs = sorted_values(refs)
            distinct_records = unique_sorted(matches)
            if len(distinct_records) == 1:
                if has(distinct_records[0],'operational_state') and get(distinct_records[0],'operational_state') is not None:
                    state = 'resolved'
                    reason = '同一immutable snapshotの原KnowledgeRecordを一意に辿れる。運用成立を意味しない。'
                else:
                    reason = '原KnowledgeRecordのoperational_stateが未供給またはnull。'
            axes.append({'subject_ref':subject,'binding':binding,'axis':'knowledge_record_trace','state':state,'original_refs':refs,'reason':reason,'backflow_owner':None if state == 'resolved' else get(subject,'owner',None)})
    return sorted_values(axes)

def comparison_usable(v,comparison):
    ref = get(comparison,'comparison_source_ref')
    if not source_usable(v,ref):
        return False
    for source in as_list(get(snapshot_input(v),'sources')):
        if ref_same(get(source,'ref'),ref):
            for original in as_list(get(get(source,'content'),'meaning_comparisons')):
                if is_object(original) and owner_body_equal(original,comparison,'comparison_source_ref'):
                    return True
    return False

def meaning_pair_axes(v,slot):
    return meaning_pair_axes_with_origins(v,slot)['axes']

def supplied_source_refs(v):
    refs = []
    for source in as_list(get(snapshot_input(v),'sources')):
        if is_object(get(source,'ref')):
            refs.append(get(source,'ref'))
    return sorted_values(refs)


def construction_issues(v):
    inp = snapshot_input(v)
    if not is_object(get(v,'input')):
        return []
    issues = []
    if not is_array(get(v,'unusable_source_refs')):
        issues.append({'locator':'','reason':'先行validation結果のsource資格不足一覧が未供給。sourceをusableへ補完しない。','source_ref':None})
    for key in ['binding','candidates','descriptors','knowledge_records','sources']:
        if not has(inp,key):
            issues.append({'locator':'/'+key,'reason':'返却constructorが読む元memberが未供給。意味充足へ補完しない。','source_ref':None})
    root_binding = get(inp,'binding')
    if is_object(root_binding) and not is_object(get(root_binding,'knowledge_ref')) and not is_object(get(root_binding,'template_ref')):
        issues.append({'locator':'/binding','reason':'root bindingのknowledge_refとtemplate_refがどちらもRefとして供給されず、依存診断subjectを構成できない。元bindingを保持し、Refを生成しない。','source_ref':None})
    candidates = as_list(get(inp,'candidates'))
    bindings = selected_bindings(v)
    for i in range(len(candidates)):
        found = False
        for binding in bindings:
            if ref_same(get(binding,'template_ref'),candidates[i]):
                found = True
        if not found:
            issues.append({'locator':'/candidates/'+str(i),'reason':'候補に同template Refのbinding/knowledge Refを結べない。','source_ref':candidates[i] if is_object(candidates[i]) else None})
    slots = as_list(get(inp,'descriptors'))
    for i in range(len(slots)):
        for key in ['binding','descriptor_kind']:
            if not has(slots[i],key):
                issues.append({'locator':'/descriptors/'+str(i)+'/'+key,'reason':'意味比較constructorが読む元memberが未供給。対象pairを未評価に保つ。','source_ref':None})
        if is_object(get(slots[i],'binding')) and not is_object(get(get(slots[i],'binding'),'template_ref')):
            issues.append({'locator':'/descriptors/'+str(i)+'/binding/template_ref','reason':'意味比較のsubject原Refが未供給。対象pairを未評価に保つ。','source_ref':None})
        facts = as_list(get(slots[i],'facts'))
        for j in range(len(facts)):
            if not is_object(get(facts[j],'ref')):
                issues.append({'locator':'/descriptors/'+str(i)+'/facts/'+str(j)+'/ref','reason':'意味定義factの原Refが未供給。返却Refを生成しない。','source_ref':get(facts[j],'source_ref') if is_object(get(facts[j],'source_ref')) else None})
    if is_array(get(inp,'knowledge_records')):
        for binding in selected_bindings(v):
            subject = get(binding,'knowledge_ref')
            matches = []
            indices = []
            records = get(inp,'knowledge_records')
            for i in range(len(records)):
                if ref_same(get(records[i],'ref'),subject):
                    matches.append(records[i])
                    indices.append(i)
            distinct = unique_sorted(matches)
            if len(distinct) == 0:
                issues.append({'locator':'/knowledge_records','reason':'同一knowledge Refの原KnowledgeRecordが未供給。','source_ref':subject})
            elif len(distinct) != 1:
                issues.append({'locator':'/knowledge_records','reason':'同一knowledge Refに異なる原本文のrecordが複数あり、一意に追跡できない。','source_ref':subject})
            elif not has(distinct[0],'operational_state'):
                issues.append({'locator':'/knowledge_records/'+str(indices[0])+'/operational_state','reason':'原KnowledgeRecordのoperational_state memberが未供給。','source_ref':subject})
            elif get(distinct[0],'operational_state') is None:
                issues.append({'locator':'/knowledge_records/'+str(indices[0])+'/operational_state','reason':'原KnowledgeRecordのoperational_stateが明示null。','source_ref':subject})
    return unique_sorted(issues)


def same_pair_pending_axes(v,slot,left,right,pair_subject):
    return same_pair_pending_axes_with_origins(v,slot,left,right,pair_subject)['axes']


def original_value_indices(values,value):
    result = []
    for index in range(len(values)):
        if json_equal(values[index],value):
            result.append(index)
    return result

def finish_meaning_pair_annotations(axes,origins):
    rows = []
    for index in range(len(axes)):
        rows.append({'axis':axes[index],'origin':origins[index]})
    ordered = sort_by_json(rows,'axis')
    final_axes = []
    final_origins = []
    for index in range(len(ordered)):
        final_axes.append(ordered[index]['axis'])
        item = ordered[index]['origin']
        item['axis_index'] = index
        final_origins.append(item)
    return {'axes':final_axes,'origins':final_origins}

def same_pair_pending_axes_with_origins(v,slot,left,right,pair_subject):
    results = []
    origins = []
    for comparison in unique_sorted(as_list(get(snapshot_input(v),'meaning_comparisons'))):
        pair = (ref_same(get(comparison,'left_fact_ref'),get(left,'ref')) and ref_same(get(comparison,'right_fact_ref'),get(right,'ref'))) or (ref_same(get(comparison,'right_fact_ref'),get(left,'ref')) and ref_same(get(comparison,'left_fact_ref'),get(right,'ref')))
        ref = get(comparison,'comparison_source_ref')
        if pair:
            unresolved = False
            reason = ''
            if not is_object(ref):
                unresolved = True
                reason = '同pairの独立比較命題のsource参照が未供給。対応結果とは別にunknownを保持する。'
            elif not source_usable(v,ref):
                unresolved = True
                reason = '同pairの独立比較命題のsourceが未資格または意味正本でない。対応結果とは別にunknownを保持する。'
            elif not comparison_usable(v,comparison):
                unresolved = True
                reason = '同pairの独立比較命題を意味正本の原bodyへ結べない。対応結果とは別にunknownを保持する。'
            elif not has(comparison,'equivalent') or get(comparison,'equivalent') is None:
                unresolved = True
                reason = '同pairの独立比較命題が未確定。対応結果とは別にunknownを保持する。'
            if unresolved:
                refs = []
                if is_object(get(left,'ref')):
                    refs.append(get(left,'ref'))
                if is_object(get(right,'ref')):
                    refs.append(get(right,'ref'))
                subject = pair_subject
                if is_object(ref):
                    refs.append(ref)
                    subject = ref
                if is_string(get(comparison,'reason')):
                    reason = reason + ' 原命題の理由: ' + get(comparison,'reason')
                else:
                    reason = reason + ' 原命題の理由は未供給またはnull。'
                results.append({'subject_ref':subject,'binding':get(slot,'binding'),'axis':'meaning_comparison_source','state':'unknown','original_refs':sorted_values(refs),'reason':reason,'backflow_owner':get(get(get(slot,'binding'),'knowledge_ref'),'owner',None)})
                origins.append({'local_emission_ordinal':len(origins),'comparison_occurrence_indices':original_value_indices(as_list(get(snapshot_input(v),'meaning_comparisons')),comparison)})
    return finish_meaning_pair_annotations(results,origins)

def meaning_pair_axes_with_origins(v,slot):
    results = []
    origins = []
    if not is_object(get(slot,'binding')) or not is_object(get(get(slot,'binding'),'template_ref')) or not has(slot,'descriptor_kind'):
        return {'axes':None,'origins':[]}
    facts = sort_by_json(unique_sorted(as_list(get(slot,'facts'))),'ref')
    for i in range(len(facts)):
        for j in range(i+1,len(facts)):
            left = facts[i]
            right = facts[j]
            matched = []
            comparison_occurrences = []
            raw_comparisons = as_list(get(snapshot_input(v),'meaning_comparisons'))
            attribution_known = get(owner_descriptor_attribution(v,slot,left),'state') == 'known' and get(owner_descriptor_attribution(v,slot,right),'state') == 'known'
            for comparison_index in range(len(raw_comparisons)):
                comparison = raw_comparisons[comparison_index]
                pair = (ref_same(get(comparison,'left_fact_ref'),get(left,'ref')) and ref_same(get(comparison,'right_fact_ref'),get(right,'ref'))) or (ref_same(get(comparison,'right_fact_ref'),get(left,'ref')) and ref_same(get(comparison,'left_fact_ref'),get(right,'ref')))
                comparison_origin = {'input_index':comparison_index,'original_value':comparison,'matched':False}
                if pair:
                    comparison_occurrences.append(comparison_origin)
                if attribution_known and pair and binding_same(get(left,'binding'),get(slot,'binding')) and binding_same(get(right,'binding'),get(slot,'binding')) and fact_usable(v,left) and fact_usable(v,right) and comparison_usable(v,comparison):
                    matched.append(comparison)
                    comparison_origin['matched'] = True
            state = 'unknown'
            reason = '同bindingのqualifiedな独立意味比較が未供給または未確定。'
            if not attribution_known:
                reason = '両factのowner descriptor帰属がknownでないため意味pairを評価しない。帰属状態はdescriptor.attribution axisへ別に保持する。'
            for comparison in matched:
                if get(comparison,'equivalent') is True and state == 'unknown':
                    state = 'known'
                    reason = '同bindingのqualifiedな独立意味比較が同義を示す。'
            for comparison in matched:
                if get(comparison,'equivalent') is False:
                    state = 'conflict'
                    reason = '同bindingのqualifiedな独立意味比較が相反を示す。'
            refs = []
            subject = get(get(slot,'binding'),'template_ref')
            if is_object(get(left,'ref')) and is_object(get(right,'ref')):
                subject = get(left,'ref')
            if is_object(get(left,'ref')):
                refs.append(get(left,'ref'))
            if is_object(get(right,'ref')):
                refs.append(get(right,'ref'))
            for ref in as_list(get(slot,'comparison_refs')):
                refs.append(ref)
            for comparison in matched:
                ref = get(comparison,'comparison_source_ref')
                if is_object(ref) and ref not in refs:
